#!/usr/bin/env python3
import rclpy
from rclpy.node import Node
from sensor_msgs.msg import Image
from geometry_msgs.msg import PoseStamped
from cv_bridge import CvBridge
import cv2
import numpy as np

class DetectionRuche(Node):
    def __init__(self):
        super().__init__('detection_ruche')
        self.bridge = CvBridge()
        
        # Subscribe to camera topic
        self.subscription = self.create_subscription(
            Image,
            '/camera/image_raw',
            self.image_callback,
            10
        )
        
        # Publish couvercle position
        self.pose_pub = self.create_publisher(
            PoseStamped,
            '/ruche/couvercle_pose',
            10
        )
        
        self.get_logger().info('Nœud de détection ruche démarré')
        
        # Couleur du couvercle en HSV (à ajuster selon ta ruche)
        self.lower_cover = np.array([0, 50, 50])    # Rouge/orange
        self.upper_cover = np.array([10, 255, 255])
        
    def detect_couvercle(self, cv_image):
        """Détecte le couvercle et retourne son centre en pixels"""
        # Convertir en HSV
        hsv = cv2.cvtColor(cv_image, cv2.COLOR_BGR2HSV)
        
        # Filtrer par couleur
        mask = cv2.inRange(hsv, self.lower_cover, self.upper_cover)
        
        # Nettoyer le masque
        mask = cv2.erode(mask, None, iterations=2)
        mask = cv2.dilate(mask, None, iterations=2)
        
        # Trouver les contours
        contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        
        if contours:
            # Prendre le plus grand contour
            largest = max(contours, key=cv2.contourArea)
            area = cv2.contourArea(largest)
            
            # Seuil minimum pour éviter les petits objets
            if area > 1000:
                # Calculer le centre
                M = cv2.moments(largest)
                if M['m00'] > 0:
                    cx = int(M['m10'] / M['m00'])
                    cy = int(M['m01'] / M['m00'])
                    return (cx, cy), largest
        
        return None, None
    
    def image_callback(self, msg):
        try:
            # Convertir ROS Image -> OpenCV
            cv_image = self.bridge.imgmsg_to_cv2(msg, 'bgr8')
            
            # Détecter le couvercle
            center, contour = self.detect_couvercle(cv_image)
            
            # Dessiner les résultats
            if center:
                cv2.circle(cv_image, center, 10, (0, 255, 0), -1)
                cv2.putText(cv_image, "Couvercle detecte", (10, 30),
                           cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)
                
                # Publier la position (en 2D pour l'instant)
                pose_msg = PoseStamped()
                pose_msg.header = msg.header
                pose_msg.pose.position.x = float(center[0])
                pose_msg.pose.position.y = float(center[1])
                self.pose_pub.publish(pose_msg)
            else:
                cv2.putText(cv_image, "Couvercle non detecte", (10, 30),
                           cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 0, 255), 2)
            
            # Afficher l'image
            cv2.imshow('Detection Ruche', cv_image)
            cv2.waitKey(1)
            
        except Exception as e:
            self.get_logger().error(f'Erreur: {e}')

def main(args=None):
    rclpy.init(args=args)
    node = DetectionRuche()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()
        cv2.destroyAllWindows()

if __name__ == '__main__':
    main()

